                    : p.length == 2 ? Kiem.tao("Product", p[0], p[1]) : Kiem.tao("Product", p[0], p[1], Long.valueOf(p[2]));
            System.out.println("[" + String.join("|", p) + "] -> " + Kiem.goi(x, "toString"));
            Object y = Kiem.goiObj(x, "withPrice", Long.valueOf(-1));
